import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.DMtjdCb-.js";const n="/help/assets/library-overview.en.iV37i4_k.png",m=JSON.parse('{"title":"Start here","description":"","frontmatter":{},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),i={name:"en/index.md"};function l(s,e,h,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h1><p>AnimeMachine brings title information, subscriptions, existing collections, and player controls into one place. Start with one complete task: find a title, download an episode, and play it. Add your existing collection and adjust other settings afterward.</p><p><img src="'+n+'" alt="Library: covers, subscriptions, and collection status" loading="lazy"></p><h2 id="choose-where-to-run-it" tabindex="-1">Choose where to run it <a class="header-anchor" href="#choose-where-to-run-it" aria-label="Permalink to &quot;Choose where to run it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your device</th><th>Start with</th></tr></thead><tbody><tr><td>Windows PC</td><td><a href="./desktop.html#windows">Desktop setup</a></td></tr><tr><td>Linux server or NAS with Docker</td><td><a href="./docker.html">Linux and Docker</a></td></tr><tr><td>macOS or Linux PC</td><td><a href="./desktop.html#macos-linux">Desktop setup</a></td></tr><tr><td>AnimeMachine is already open</td><td><a href="./first-use.html">First login</a></td></tr></tbody></table><p>The desktop package runs AnimeMachine; connect download services when needed. The default NAS stack also starts Ani-RSS, qBittorrent, and Torrent Collector, and connects them automatically.</p><h2 id="complete-your-first-workflow" tabindex="-1">Complete your first workflow <a class="header-anchor" href="#complete-your-first-workflow" aria-label="Permalink to &quot;Complete your first workflow&quot;">​</a></h2><ol><li>Deploy on your device, then <a href="./first-use.html">sign in and check the page</a>.</li><li><a href="./subscribe.html">Subscribe to one title</a> and choose a subtitle and release variant.</li><li>Once an episode is available, <a href="./playback.html">open it in your player</a>.</li><li>Then try <a href="./continue-watching.html">Continue watching</a> or <a href="./collections.html">connect an existing collection</a>.</li></ol><p>The main example is the Witch title shown in the screenshots, searchable by its Japanese name <strong>世界最強の魔女、始めました</strong>. Available episodes and releases change over time; choose from the current results.</p><h2 id="follow-along" tabindex="-1">Follow along <a class="header-anchor" href="#follow-along" aria-label="Permalink to &quot;Follow along&quot;">​</a></h2><p>Each chapter covers one task and uses the actual button labels. Click an image to open its full resolution. Switch between 中文, English, and 日本語 at the top of the page.</p><p>Skip tasks you have already completed. For a specific problem, use <a href="./troubleshooting.html">Troubleshooting</a> or the notes at the end of the relevant chapter.</p>',12)])])}const f=t(i,[["render",l]]);export{m as __pageData,f as default};
